  H.add_edge(p,q,path=path,length=sum(np.linalg.norm(np.array(path[i+1])-path[i]) for i in range(len(path)-1)))
print('nodes',len(H),'edges',len(H.edges));
for i,p in enumerate(H): print(i,p,H.degree(p),[(list(H).index(q),round(H[p][q]['length'],1)) for q in H[p]])
# image
out=cv2.resize(im[478:569,135:875],(2220,273),interpolation=cv2.INTER_NEAREST)
for x,y in G:
 if 135<=x<875 and 478<=y<569: cv2.circle(out,(3*(x-135)+1,3*(y-478)+1),1,(255,0,0),-1)
for i,(x,y) in enumerate(H):
 cv2.circle(out,(3*(x-135)+1,3*(y-478)+1),3,(0,180,20),-1)
 cv2.putText(out,str(i),(3*(x-135),3*(y-478)-6),cv2.FONT_HERSHEY_SIMPLEX,.35,(20,70,220),1)
Image.fromarray(out).save('/app/output/skeleton.png')
import pickle
pickle.dump((G,H),open('/app/output/graph.pkl','wb'))
